let canvasContext;
let canvasCenterX, canvasCenterY;
let arcElements = [];
let circleElements = [];
let isArcMode;
let frameCounter = 0;
const colorPalette = ['#ff0000', '#00ff00', '#0000ff'];

function setup() {
  createCanvas(900, 900);
  rectMode(CENTER);
  blendMode(ADD);
  colorMode(HSB, 360, 100, 100, 100);
  canvasContext = drawingContext;
  canvasCenterX = width / 2;
  canvasCenterY = height / 2;
  initializeElements();
}

function draw() {
  clear();
  background('#000000');

  if (isArcMode) {
    for (let arc of arcElements) {
      arc.render();
    }
  } else {
    for (let circle of circleElements) {
      circle.render();
    }
  }

  if ((frameCounter % 180) === 0) {
    isArcMode = false;
  }
  if ((frameCounter % 300) === 0) {
    initializeElements();
  }

  frameCounter++;
}

function initializeElements() {
  arcElements = [];
  circleElements = [];
  const gridSize = width;
  const gridCellCount = 7;
  const cellSize = gridSize / gridCellCount;
  const elementSize = cellSize;

  for (let row = -1; row <= gridCellCount + 1; row++) {
    for (let col = -1; col <= gridCellCount + 1; col++) {
      const x = col * cellSize + cellSize / 2 + (width - gridSize) / 2;
      const y = row * cellSize + cellSize / 2 + (height - gridSize) / 2;
      const distance = dist(canvasCenterX, canvasCenterY, x, y);

      for (let k = 0; k < 4; k++) {
        for (let l = 0; l < 3; l++) {
          const arcDelay = -Math.floor(distance * 0.2) - l * 3;
          arcElements.push(new Arc(x, y, elementSize, k, arcDelay, colorPalette[l]));
        }
      }

      const circleRotationOffset = (((row % 2) + col) % 2) * 2;
      for (let l = 0; l < 3; l++) {
        const circleDelay = -Math.floor(x / 20) - l * 3;
        circleElements.push(
          new Circle(
            x - elementSize / 2,
            y - elementSize / 2,
            elementSize * 0.5,
            circleRotationOffset,
            circleDelay,
            elementSize,
            colorPalette[l]
          )
        );
      }
    }
  }
  frameCounter = 0;
  isArcMode = true;
}

function easeInOutQuad(t) {
  return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
}

class Arc {
  constructor(x, y, size, rotationIndex, delay, color) {
    this.x = x;
    this.y = y;
    this.size = size;
    this.rotation = rotationIndex * (TAU / 4);
    this.startAngle = 0;
    this.endAngle = PI / 2;
    this.currentAngle = 0;
    this.frameCounter = delay;
    this.animationDuration = 70;
    this.offset = 0;
    this.diameter = this.size * 0.5;
    this.color = color;
  }

  display() {
    push();
    translate(this.x, this.y);
    rotate(this.rotation);
    noStroke();
    fill(this.color);
    arc(
      -this.size / 2 + this.offset,
      -this.size / 2,
      this.diameter,
      this.diameter,
      this.currentAngle,
      this.currentAngle + PI / 2
    );
    pop();
  }

  update() {
    if (this.frameCounter > 0 && this.frameCounter < this.animationDuration) {
      const normalizedTime = norm(this.frameCounter, 0, this.animationDuration - 1);
      this.currentAngle = lerp(this.startAngle, this.endAngle, easeInOutQuad(normalizedTime));
      this.offset = lerp(0, this.size, easeInOutQuad(normalizedTime));
    }
    this.frameCounter++;
  }

  render() {
    this.display();
    this.update();
  }
}

class Circle {
  constructor(x, y, diameter, rotationOffset, delay, moveDistance, color) {
    this.x = x;
    this.y = y;
    this.diameter = diameter;
    this.rotationDirection = rotationOffset * (TAU / 4);
    this.frameCounter = delay;
    this.moveDistance = moveDistance;
    this.angle = PI;
    this.animationDuration = 70;
    this.color = color;
  }

  display() {
    noStroke();
    fill(this.color);
    push();
    translate(
      this.x + this.moveDistance * 0.5 * cos(this.rotationDirection),
      this.y + this.moveDistance * 0.5 * sin(this.rotationDirection)
    );
    rotate(this.angle);
    circle(
      this.moveDistance * 0.5 * cos(this.rotationDirection - PI),
      this.moveDistance * 0.5 * sin(this.rotationDirection - PI),
      this.diameter
    );
    pop();
  }

  update() {
    if (this.frameCounter > 0 && this.frameCounter < this.animationDuration) {
      const normalizedTime = norm(this.frameCounter, 0, this.animationDuration - 1);
      this.angle = lerp(PI, 0, easeInOutQuad(normalizedTime));
    }
    this.frameCounter++;
  }

  render() {
    this.display();
    this.update();
  }
}

